var e={country:`国家`,repOffice:`代表处`,region:`地区部`,companyTag:`公司标签`,invoiceNo:`发票号`,refNo:`其他相关编号`,accountant:`会计`,scannedBy:`扫描员`,issueDateRange:`开立日期`,maturityDateRange:`到期日`,lgExpiryDateRange:`保函失效日期`,lgLedgerStatus:`保函台账状态`,bankName:`银行名称`,currency:`币种`,amount:`金额`,issuingAuthority:`签发机构`,disposalTimeRange:`报废时间`,businessVolumeNo:`业务册号`,lgWorkflowNo:`保函电子流编号`,lgNo:`保函编号`},t={country:`ALL`,repOffice:`ALL`,region:`ALL`,companyTag:`ALL`,invoiceNo:`ACCOUNTING_OR_TAX`,refNo:`ALL`,accountant:`ACCOUNTING`,scannedBy:`ACCOUNTING`,issueDateRange:`FUND`,maturityDateRange:`FUND_OR_NON_FIN`,lgExpiryDateRange:`FUND`,lgLedgerStatus:`FUND`,bankName:`FUND`,currency:`TAX_OR_FUND`,amount:`TAX_OR_FUND`,issuingAuthority:`NON_FIN`,disposalTimeRange:`ACCOUNTING`,businessVolumeNo:`ACCOUNTING`,lgWorkflowNo:`FUND`,lgNo:`FUND`},n=[`country`,`repOffice`,`region`,`companyTag`,`invoiceNo`,`refNo`,`accountant`,`scannedBy`,`issueDateRange`,`maturityDateRange`,`lgExpiryDateRange`,`lgLedgerStatus`,`bankName`,`currency`,`amount`,`issuingAuthority`,`disposalTimeRange`,`businessVolumeNo`,`lgWorkflowNo`,`lgNo`],r=(e,n)=>{let r=t[e];if(!r)return!0;let i=n.includes(`会计`),a=n.includes(`税务`),o=n.includes(`资金`),s=n.includes(`非财经`);switch(r){case`ACCOUNTING_OR_TAX`:return i||a;case`ACCOUNTING`:return i;case`FUND`:return o;case`FUND_OR_NON_FIN`:return o||s;case`TAX_OR_FUND`:return a||o;case`NON_FIN`:return s;default:return!0}};export{e as n,r,n as t};